# compare logical values per type
cmp_cmd() { # db key
  local db=$1 k=$2 t
  t=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db type "$k" | tr -d '\r')
  case "$t" in
    string) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db get "$k"); nc=$(redis-cli -p 6380 -n $db get "$k");;
    list) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db lrange "$k" 0 -1 | sort); nc=$(redis-cli -p 6380 -n $db lrange "$k" 0 -1 | sort);;
    set) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db smembers "$k" | sort); nc=$(redis-cli -p 6380 -n $db smembers "$k" | sort);;
    zset) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db zrange "$k" 0 -1 withscores | paste -sd,); nc=$(redis-cli -p 6380 -n $db zrange "$k" 0 -1 withscores | paste -sd,);;
    hash) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db hgetall "$k" | paste -sd,); nc=$(redis-cli -p 6380 -n $db hgetall "$k" | paste -sd,);;
    stream) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db xrange "$k" - +); nc=$(redis-cli -p 6380 -n $db xrange "$k" - +);;
    *) oc="type:$t"; nc=$(redis-cli -p 6380 -n $db type "$k" | tr -d '\r');;
  esac
  [ "$oc" != "$nc" ] && { echo "MISMATCH db$db [$k] ($t)"; return 1; }
}
bad=0
for db in $(seq 0 15); do
  while IFS= read -r k; do [ -z "$k" ] && continue; cmp_cmd $db "$k" || bad=1; done < /tmp/old_keys_$db.txt
done
[ $bad -eq 0 ] && echo "ALL logical values match"

cat > /tmp/cmp.sh <<'EOF'
#!/bin/bash
exec 2>/dev/null
cmp_cmd() {
  local db=$1 k=$2 t oc nc
  t=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db type "$k" | tr -d '\r')
  case "$t" in
    string) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db --no-raw get "$k" | md5sum); nc=$(redis-cli -p 6380 -n $db --no-raw get "$k" | md5sum);;
    list) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db --no-raw lrange "$k" 0 -1 | sort | md5sum); nc=$(redis-cli -p 6380 -n $db --no-raw lrange "$k" 0 -1 | sort | md5sum);;
    set) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db --no-raw smembers "$k" | sort | md5sum); nc=$(redis-cli -p 6380 -n $db --no-raw smembers "$k" | sort | md5sum);;
    zset) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db --no-raw zrange "$k" 0 -1 withscores | paste -sd, | md5sum); nc=$(redis-cli -p 6380 -n $db --no-raw zrange "$k" 0 -1 withscores | paste -sd, | md5sum);;
    hash) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db --no-raw hgetall "$k" | paste -sd, | md5sum); nc=$(redis-cli -p 6380 -n $db --no-raw hgetall "$k" | paste -sd, | md5sum);;
    stream) oc=$(/opt/redis-7.2/bin/redis-cli -p 6379 -n $db --no-raw xrange "$k" - + | md5sum); nc=$(redis-cli -p 6380 -n $db --no-raw xrange "$k" - + | md5sum);;
    *) oc="t:$t"; nc="t:$(redis-cli -p 6380 -n $db type "$k" | tr -d '\r')";;
  esac
  if [ "$oc" != "$nc" ]; then echo "MISMATCH db$db [$k] ($t)"; return 1; fi
}
bad=0; n=0
for db in $(seq 0 15); do
  while IFS= read -r k; do [ -z "$k" ] && continue; n=$((n+1)); cmp_cmd $db "$k" || bad=1; done < /tmp/old_keys_$db.txt
done
echo "checked=$n mismatches=$bad"
EOF
bash /tmp/cmp.sh
